db.messages.aggregate([
  { $match: { receivedAt: { $gte: ISODate('2022-01-01') } } },
  { $group: {
      _id: { channel: '$channel', day: { $dateTrunc: { date: '$receivedAt', unit: 'day' } } },
      conversations: { $addToSet: '$conversationId' },
  } },
  { $project: { conversations: { $size: '$conversations' } } },
  { $sort: { '_id.day': 1 } },
]);

// SHA-256 y no bcrypt: el token ya es aleatorio de 256 bits, no hace falta
// un hash lento y sí una búsqueda por índice.
func hashRefreshToken(plain string) []byte {
    sum := sha256.Sum256([]byte(plain))
    return sum[:]
}

